5	/**
6	 * Durably completes one authenticated successor without publishing its AHE head.
7	 * @param input - Exact genuine close handle and owner-bound adoption intent.
8	 * @returns Opaque staged custody or a typed fail-closed result.
9	 */
10	export function stageCreatorSuccessorAdoption(input: unknown): Promise<Readonly<Record<string, unknown>>> {
11		return consumeCreatorAdoptionStage(input);
12	}
13	
14	/**
15	 * Publishes one owner-bound staged successor through the exact AHE head CAS.
16	 * @param input - Exact staged capability and genuine close handle.
17	 * @returns Existing prepared-activation custody or a typed fail-closed result.
18	 */
19	export function publishStagedCreatorSuccessorAdoption(input: unknown): Promise<Readonly<Record<string, unknown>>> {
20		return consumeCreatorAdoptionPublish(input);
21	}

1	import "./creator-adoption.js";
2	
3	import {
4		consumeCreatorAdoptionPendingRecovery,
5		type CreatorAdoptionPendingRecoveryInput,
6	} from "./internal/creator-adoption-recover.js";
7	
8	const INPUT_KEYS = Object.freeze([
9		"authenticationProfile",
10		"catalog",
11		"detachedSignature",
12		"exactCanonicalAnchorPreimageBytes",
13		"exactCanonicalParametersCarrierBytes",
14		"expectedNextRoomHead",
15		"expectedPreviousRoomHead",
16		"pinnedGenesisAnchorDigest",
17		"snapshotDeclaration",
18		"snapshotStore",
19		"store",
20	]);
21	
22	function capture(value: unknown): CreatorAdoptionPendingRecoveryInput | undefined {
23		try {
24			if (value === null || typeof value !== "object" || Object.getPrototypeOf(value) !== Object.prototype) {
25				return undefined;
26			}
27			const keys = Reflect.ownKeys(value);
28			if (keys.length !== INPUT_KEYS.length || keys.some((key) => typeof key !== "string" || !INPUT_KEYS.includes(key))) {
29				return undefined;
30			}
31			const output: Record<string, unknown> = Object.create(null) as Record<string, unknown>;
32			for (const key of INPUT_KEYS) {
33				const descriptor = Object.getOwnPropertyDescriptor(value, key);
34				if (descriptor === undefined || descriptor.enumerable !== true || !("value" in descriptor)) return undefined;
35				output[key] = descriptor.value;
36			}
37			return output as unknown as CreatorAdoptionPendingRecoveryInput;
38		} catch {
39			return undefined;
40		}
41	}
42	
43	/**
44	 * Authenticates and publishes a provider-selected pending successor without live activation.
45	 * @param input - Exact copied provider heads, genesis carriers, snapshot owners and AHE store.
46	 * @returns Published stable room head or a typed fail-closed result.
47	 */
48	export function recoverPendingCreatorSuccessorAdoption(input: unknown): Promise<Readonly<Record<string, unknown>>> {
49		const captured = capture(input);
50		return captured === undefined
51			? Promise.resolve(
52					Object.freeze({
53						detail: "creator adoption pending recovery input is invalid",
54						kind: "malformed-input",
55						ok: false,
56					})
57				)
58			: consumeCreatorAdoptionPendingRecovery(captured);
59	}

1	type Result = Readonly<Record<string, unknown>>;
2	type StageOwner = (input: unknown) => Promise<Result>;
3	
4	let publishOwner: StageOwner | undefined;
5	let stageOwner: StageOwner | undefined;
6	
7	/**
8	 * Installs the sole private durable-stage owner.
9	 * @param owner - Authenticated stage kernel.
10	 * @returns Whether the owner was installed.
11	 */
12	export function installCreatorAdoptionStage(owner: StageOwner): boolean {
13		if (stageOwner !== undefined) return false;
14		stageOwner = owner;
15		return true;
16	}
17	
18	/**
19	 * Installs the sole private staged-publication owner.
20	 * @param owner - Authenticated head-publication kernel.
21	 * @returns Whether the owner was installed.
22	 */
23	export function installCreatorAdoptionPublish(owner: StageOwner): boolean {
24		if (publishOwner !== undefined) return false;
25		publishOwner = owner;
26		return true;
27	}
28	
29	/**
30	 * Executes the installed private durable-stage owner.
31	 * @param input - Exact public stage input.
32	 * @returns Frozen stage result.
33	 */
34	export function consumeCreatorAdoptionStage(input: unknown): Promise<Result> {
35		return stageOwner === undefined
36			? Promise.resolve(
37					Object.freeze({
38						detail: "creator adoption stage owner is unavailable",
39						kind: "internal-invariant",
40						ok: false,
41					})
42				)
43			: stageOwner(input);
44	}
45	
46	/**
47	 * Executes the installed private staged-publication owner.
48	 * @param input - Exact public publication input.
49	 * @returns Frozen publication result.
50	 */
51	export function consumeCreatorAdoptionPublish(input: unknown): Promise<Result> {
52		return publishOwner === undefined
53			? Promise.resolve(
54					Object.freeze({
55						detail: "creator adoption publish owner is unavailable",
56						kind: "internal-invariant",
57						ok: false,
58					})
59				)
60			: publishOwner(input);
61	}

1	import type { TrustedBlueprintCatalog } from "@ts-drp/blueprint-catalog";
2	import type { AheDurableStore } from "@ts-drp/storage";
3	import type {
4		SnapshotQuarantineDeclaration,
5		SnapshotQuarantineStore,
6		SnapshotVerificationReceipt,
7	} from "@ts-drp/storage/snapshot-transfer";
8	
9	export interface CreatorAdoptionRoomHead {
10		readonly currentAnchorDigest: string;
11		readonly epoch: number;
12		readonly objectId: string;
13	}
14	
15	export interface CreatorAdoptionPendingRecoveryInput {
16		readonly authenticationProfile: "creator-only";
17		readonly catalog: TrustedBlueprintCatalog;
18		readonly detachedSignature: Uint8Array;
19		readonly exactCanonicalAnchorPreimageBytes: Uint8Array;
20		readonly exactCanonicalParametersCarrierBytes: Uint8Array;
21		readonly expectedNextRoomHead: CreatorAdoptionRoomHead;
22		readonly expectedPreviousRoomHead: CreatorAdoptionRoomHead;
23		readonly pinnedGenesisAnchorDigest: string;
24		readonly snapshotDeclaration: SnapshotQuarantineDeclaration;
25		readonly snapshotStore: SnapshotQuarantineStore<SnapshotVerificationReceipt>;
26		readonly store: AheDurableStore;
27	}
28	
29	export type CreatorAdoptionPendingRecoveryResult =
30		| Readonly<{
31				readonly head: CreatorAdoptionRoomHead;
32				readonly lifecycle: "successor-published";
33				readonly ok: true;
34				readonly recovery: "active-new";
35		  }>
36		| Readonly<{ readonly detail: string; readonly kind: string; readonly ok: false }>;
37	
38	type RecoveryOwner = (input: CreatorAdoptionPendingRecoveryInput) => Promise<CreatorAdoptionPendingRecoveryResult>;
39	
40	let owner: RecoveryOwner | undefined;
41	
42	/**
43	 * Installs the sole private non-activating pending-recovery owner.
44	 * @param candidate - Authenticated durable recovery kernel.
45	 * @returns Whether the owner was installed.
46	 */
47	export function installCreatorAdoptionPendingRecovery(candidate: RecoveryOwner): boolean {
48		if (owner !== undefined) return false;
49		owner = candidate;
50		return true;
51	}
52	
53	/**
54	 * Executes the installed private non-activating recovery owner.
55	 * @param input - Exact copied provider heads and durable authentication carriers.
56	 * @returns Published room head or typed fail-closed result.
57	 */
58	export function consumeCreatorAdoptionPendingRecovery(
59		input: CreatorAdoptionPendingRecoveryInput
60	): Promise<CreatorAdoptionPendingRecoveryResult> {
61		return owner === undefined
62			? Promise.resolve(
63					Object.freeze({
64						detail: "creator adoption pending recovery owner is unavailable",
65						kind: "internal-invariant",
66						ok: false,
67					})
68				)
69			: owner(input);
70	}

1	import { decodeCanonical } from "@ts-drp/canonical";
2	import type { GenerationId, GenerationRef, PresentHead } from "@ts-drp/storage";
3	
4	import type { CreatorSuccessorLiveMaterial, CreatorSuccessorLiveSeed } from "./creator-successor-live.js";
5	
6	export type CreatorAdoptionIntent = Readonly<Record<never, never>>;
7	export type PreparedCreatorSuccessorAdoption = Readonly<Record<never, never>>;
8	export type StagedCreatorSuccessorAdoption = Readonly<Record<never, never>>;
9	
10	export interface CreatorAdoptionIntentMaterial {
11		readonly activation: CreatorSuccessorLiveSeed;
12		readonly candidateReferences: readonly GenerationRef[];
13		readonly exactCanonicalProjectionBytes: Uint8Array;
14		readonly generationId: GenerationId;
15		readonly pendingHead: PresentHead;
16		readonly pendingReferences: readonly GenerationRef[];
17		readonly predecessorLiveRef: GenerationRef;
18	}
19	
20	export interface PreparedCreatorSuccessorAdoptionMaterial {
21		readonly activation: CreatorSuccessorLiveMaterial;
22		readonly descriptor: Readonly<Record<string, unknown>>;
23		readonly exactCanonicalProjectionBytes: Uint8Array;
24		readonly head: PresentHead;
25	}
26	
27	export type PreparedCreatorSuccessorAdoptionInput = Omit<PreparedCreatorSuccessorAdoptionMaterial, "descriptor">;
28	
29	export interface StagedCreatorSuccessorAdoptionMaterial {
30		readonly descriptor: Readonly<Record<string, unknown>>;
31		readonly intent: CreatorAdoptionIntentMaterial;
32	}
33	
34	const custody = new WeakMap<
35		object,
36		Readonly<{ readonly material: CreatorAdoptionIntentMaterial; readonly owner: object }>
37	>();
38	const sealedFacts = new WeakMap<object, object>();
39	const preparedCustody = new WeakMap<
40		object,
41		Readonly<{ readonly material: PreparedCreatorSuccessorAdoptionInput; readonly owner: object }>
42	>();
43	const stagedCustody = new WeakMap<
44		object,
45		Readonly<{ readonly material: StagedCreatorSuccessorAdoptionMaterial; readonly owner: object }>
46	>();
47	
48	function copiedRef(ref: GenerationRef): GenerationRef {
49		return Object.freeze({ byteLength: ref.byteLength, digest: ref.digest });
50	}
51	
52	function copiedHead(head: PresentHead): PresentHead {
53		return Object.freeze({ ...head });
54	}
55	
56	function decodedDescriptor(bytes: Uint8Array): Readonly<Record<string, unknown>> {
57		const decoded = decodeCanonical(bytes);
58		if (decoded === null || typeof decoded !== "object" || Array.isArray(decoded)) {
59			throw new TypeError("prepared creator successor descriptor is invalid");
60		}
61		return Object.freeze(decoded as Record<string, unknown>);
62	}
63	
64	/**
65	 * Retains facts authenticated by a genuine close behind the internal module boundary.
66	 * @param owner - Genuine sealed close handle.
67	 * @param facts - Private detached close facts.
68	 * @returns Whether this was the first installation for the owner.
69	 */
70	export function installCreatorAdoptionFacts(owner: object, facts: object): boolean {
71		if (sealedFacts.has(owner)) return false;
72		sealedFacts.set(owner, facts);
73		return true;
74	}
75	
76	/**
77	 * Resolves private close facts for the verifier without exposing them on a public export.
78	 * @param owner - Candidate genuine sealed close handle.
79	 * @returns Private facts, or undefined for an unknown handle.
80	 */
81	export function resolveCreatorAdoptionFacts<T extends object>(owner: object): T | undefined {
82		return sealedFacts.get(owner) as T | undefined;
83	}
84	
85	/**
86	 * Revokes the predecessor's private verifier facts after successor activation.
87	 * @param owner - Genuine sealed predecessor handle.
88	 * @returns Whether private facts were present and revoked.
89	 */
90	export function revokeCreatorAdoptionFacts(owner: object): boolean {
91		return sealedFacts.delete(owner);
92	}
93	
94	/**
95	 * Creates one opaque, owner-bound, destructively consumable adoption intent.
96	 * @param owner - Genuine close handle that owns consumption.
97	 * @param material - Detached verified successor projection.
98	 * @returns Opaque intent with no serializable authority.
99	 */
100	export function createCreatorAdoptionIntent(
101		owner: object,
102		material: CreatorAdoptionIntentMaterial
103	): CreatorAdoptionIntent {
104		const intent = Object.freeze({}) as CreatorAdoptionIntent;
105		custody.set(
106			intent,
107			Object.freeze({
108				material: Object.freeze({
109					activation: material.activation,
110					candidateReferences: Object.freeze(material.candidateReferences.map(copiedRef)),
111					exactCanonicalProjectionBytes: Uint8Array.from(material.exactCanonicalProjectionBytes),
112					generationId: material.generationId,
113					pendingHead: copiedHead(material.pendingHead),
114					pendingReferences: Object.freeze(material.pendingReferences.map(copiedRef)),
115					predecessorLiveRef: copiedRef(material.predecessorLiveRef),
116				}),
117				owner,
118			})
119		);
120		return intent;
121	}
122	
123	/**
124	 * Consumes a genuine intent exactly once when presented by its bound close handle.
125	 * @param intent - Opaque candidate intent.
126	 * @param owner - Expected genuine close handle.
127	 * @returns Detached verified projection material, or undefined.
128	 */
129	export function consumeCreatorAdoptionIntent(
130		intent: unknown,
131		owner: unknown
132	): CreatorAdoptionIntentMaterial | undefined {
133		if (intent === null || typeof intent !== "object" || owner === null || typeof owner !== "object") return undefined;
134		const retained = custody.get(intent);
135		if (retained === undefined || retained.owner !== owner) return undefined;
136		custody.delete(intent);
137		return Object.freeze({
138			activation: retained.material.activation,
139			candidateReferences: Object.freeze(retained.material.candidateReferences.map(copiedRef)),
140			exactCanonicalProjectionBytes: Uint8Array.from(retained.material.exactCanonicalProjectionBytes),
141			generationId: retained.material.generationId,
142			pendingHead: copiedHead(retained.material.pendingHead),
143			pendingReferences: Object.freeze(retained.material.pendingReferences.map(copiedRef)),
144			predecessorLiveRef: copiedRef(retained.material.predecessorLiveRef),
145		});
146	}
147	
148	/**
149	 * Creates one opaque successor-preparation capability for the later activation owner.
150	 * @param owner - Genuine sealed close handle.
151	 * @param material - Authenticated durable successor result.
152	 * @returns Opaque process-local capability.
153	 */
154	export function createPreparedCreatorSuccessorAdoption(
155		owner: object,
156		material: PreparedCreatorSuccessorAdoptionInput
157	): PreparedCreatorSuccessorAdoption {
158		const capability = Object.freeze({}) as PreparedCreatorSuccessorAdoption;
159		preparedCustody.set(
160			capability,
161			Object.freeze({
162				material: Object.freeze({
163					activation: material.activation,
164					exactCanonicalProjectionBytes: Uint8Array.from(material.exactCanonicalProjectionBytes),
165					head: copiedHead(material.head),
166				}),
167				owner,
168			})
169		);
170		return capability;
171	}
172	
173	/**
174	 * Destructively consumes one genuine successor-preparation capability.
175	 * @param capability - Opaque candidate capability.
176	 * @param owner - Genuine sealed close owner.
177	 * @returns Detached successor material, or undefined.
178	 */
179	export function consumePreparedCreatorSuccessorAdoption(
180		capability: unknown,
181		owner: unknown
182	): PreparedCreatorSuccessorAdoptionMaterial | undefined {
183		if (capability === null || typeof capability !== "object" || owner === null || typeof owner !== "object") {
184			return undefined;
185		}
186		const retained = preparedCustody.get(capability);
187		if (retained === undefined || retained.owner !== owner) return undefined;
188		preparedCustody.delete(capability);
189		const exactCanonicalProjectionBytes = Uint8Array.from(retained.material.exactCanonicalProjectionBytes);
190		return Object.freeze({
191			activation: retained.material.activation,
192			descriptor: decodedDescriptor(exactCanonicalProjectionBytes),
193			exactCanonicalProjectionBytes,
194			head: copiedHead(retained.material.head),
195		});
196	}
197	
198	/**
199	 * Creates one opaque owner-bound capability for a complete unpublished successor.
200	 * @param owner - Genuine sealed close handle.
201	 * @param material - Authenticated staged successor material.
202	 * @returns Opaque process-local staged capability.
203	 */
204	export function createStagedCreatorSuccessorAdoption(
205		owner: object,
206		material: StagedCreatorSuccessorAdoptionMaterial
207	): StagedCreatorSuccessorAdoption {
208		const capability = Object.freeze({}) as StagedCreatorSuccessorAdoption;
209		stagedCustody.set(
210			capability,
211			Object.freeze({
212				material: Object.freeze({
213					descriptor: Object.freeze({ ...material.descriptor }),
214					intent: material.intent,
215				}),
216				owner,
217			})
218		);
219		return capability;
220	}
221	
222	/**
223	 * Destructively consumes one genuine staged capability for its bound close handle.
224	 * @param capability - Opaque staged capability candidate.
225	 * @param owner - Expected genuine close handle.
226	 * @returns Authenticated staged material, or undefined.
227	 */
228	export function consumeStagedCreatorSuccessorAdoption(
229		capability: unknown,
230		owner: unknown
231	): StagedCreatorSuccessorAdoptionMaterial | undefined {
232		if (capability === null || typeof capability !== "object" || owner === null || typeof owner !== "object") {
233			return undefined;
234		}
235		const retained = stagedCustody.get(capability);
236		if (retained === undefined || retained.owner !== owner) return undefined;
237		stagedCustody.delete(capability);
238		return Object.freeze({
239			descriptor: Object.freeze({ ...retained.material.descriptor }),
240			intent: retained.material.intent,
241		});
242	}

1	import { decodeCanonical, encodeCanonical } from "@ts-drp/canonical";
2	import { inspectCreatorTrustAdvance } from "@ts-drp/control-plane/creator-trust-advance";
3	import type { CurrentAnchorTrust } from "@ts-drp/protocol-v3";
4	import { openCreatorSuccessorTrust } from "@ts-drp/protocol-v3/creator-close";
5	import {
6		type AheDurableStore,
7		digestBlob,
8		digestClosure,
9		type GenerationPageCursor,
10		type GenerationRecord,
11		type GenerationRef,
12		type PresentHead,
13	} from "@ts-drp/storage";
14	
15	import type { CreatorLiveCloseResult } from "./creator-close.js";
16	import {
17		consumeCreatorAdoptionIntent,
18		consumeStagedCreatorSuccessorAdoption,
19		createPreparedCreatorSuccessorAdoption,
20		createStagedCreatorSuccessorAdoption,
21		type CreatorAdoptionIntentMaterial,
22		type PreparedCreatorSuccessorAdoption,
23		resolveCreatorAdoptionFacts,
24		type StagedCreatorSuccessorAdoption,
25	} from "./internal/creator-adoption-intent.js";
26	import { installCreatorAdoptionPublish, installCreatorAdoptionStage } from "./internal/creator-adoption-stage.js";
27	import { completeCreatorSuccessorLiveMaterial } from "./internal/creator-successor-live.js";
28	
29	type FailureKind =
30		| "malformed-input"
31		| "intent-unavailable"
32		| "recovery-failed"
33		| "chain-invalid"
34		| "pending-old"
35		| "stale-head"
36		| "storage-failed"
37		| "internal-invariant";
38	
39	type CommitFailure = Readonly<{ readonly detail: string; readonly kind: FailureKind; readonly ok: false }>;
40	type CommitSuccess = Readonly<{
41		readonly capability: PreparedCreatorSuccessorAdoption;
42		readonly descriptor: Readonly<Record<string, unknown>>;
43		readonly head: PresentHead;
44		readonly lifecycle: "successor-prepared";
45		readonly ok: true;
46		readonly recovery: "active-new";
47	}>;
48	type StageSuccess = Readonly<{
49		readonly capability: StagedCreatorSuccessorAdoption;
50		readonly descriptor: Readonly<Record<string, unknown>>;
51		readonly lifecycle: "successor-staged";
52		readonly ok: true;
53		readonly recovery: "pending-old";
54	}>;
55	type PublishSuccess = CommitSuccess;
56	
57	interface SealedAdoptionFacts {
58		readonly closeResult: CreatorLiveCloseResult;
59		readonly currentHead: PresentHead;
60		readonly currentReferences: readonly GenerationRef[];
61		readonly currentTrust: CurrentAnchorTrust;
62		readonly durableReplay: Readonly<{ verify(): Promise<boolean> }>;
63		readonly history: object;
64		readonly objectId: Parameters<AheDurableStore["recoverActiveGeneration"]>[0];
65		readonly proposedHead: PresentHead;
66		readonly proposedReferences: readonly GenerationRef[];
67		readonly snapshotDeclaration: object;
68		readonly snapshotStore: object;
69		readonly store: AheDurableStore;
70	}
71	
72	interface CapturedInput {
73		readonly handle: object;
74		readonly intent: object;
75	}
76	
77	interface CapturedPublishInput {
78		readonly capability: object;
79		readonly handle: object;
80	}
81	
82	type Candidate = Readonly<{ readonly bytes: Uint8Array; readonly ref: GenerationRef }>;
83	type Terminal =
84		| Readonly<{ readonly head: PresentHead; readonly kind: "active-new" }>
85		| Readonly<{ readonly head: PresentHead; readonly kind: "pending-old" }>
86		| Readonly<{ readonly kind: "stale-head" }>
87		| Readonly<{ readonly kind: "recovery-failed" }>
88		| Readonly<{ readonly kind: "chain-invalid" }>;
89	type StagedTerminal =
90		| Readonly<{ readonly kind: "staged" }>
91		| Readonly<{ readonly kind: "pending-old" }>
92		| Readonly<{ readonly kind: "stale-head" }>
93		| Readonly<{ readonly kind: "recovery-failed" }>
94		| Readonly<{ readonly kind: "chain-invalid" }>;
95	
96	function failure(kind: FailureKind, detail: string): CommitFailure {
97		return Object.freeze({ detail, kind, ok: false as const });
98	}
99	
100	function record(value: unknown): value is Readonly<Record<string, unknown>> {
101		return value !== null && typeof value === "object" && !Array.isArray(value);
102	}
103	
104	function captureInput(value: unknown): CapturedInput | undefined {
105		try {
106			if (!record(value) || Object.keys(value).sort().join(",") !== "handle,intent") return undefined;
107			const handle = Object.getOwnPropertyDescriptor(value, "handle");
108			const intent = Object.getOwnPropertyDescriptor(value, "intent");
109			return handle !== undefined &&
110				"value" in handle &&
111				record(handle.value) &&
112				intent !== undefined &&
113				"value" in intent &&
114				record(intent.value)
115				? Object.freeze({ handle: handle.value, intent: intent.value })
116				: undefined;
117		} catch {
118			return undefined;
119		}
120	}
121	
122	function capturePublishInput(value: unknown): CapturedPublishInput | undefined {
123		try {
124			if (!record(value) || Object.keys(value).sort().join(",") !== "capability,handle") return undefined;
125			const capability = Object.getOwnPropertyDescriptor(value, "capability");
126			const handle = Object.getOwnPropertyDescriptor(value, "handle");
127			return capability !== undefined &&
128				"value" in capability &&
129				record(capability.value) &&
130				handle !== undefined &&
131				"value" in handle &&
132				record(handle.value)
133				? Object.freeze({ capability: capability.value, handle: handle.value })
134				: undefined;
135		} catch {
136			return undefined;
137		}
138	}
139	
140	function sameBytes(left: Uint8Array, right: Uint8Array): boolean {
141		return left.byteLength === right.byteLength && left.every((byte, index) => byte === right[index]);
142	}
143	
144	function sameRef(left: GenerationRef, right: GenerationRef): boolean {
145		return left.byteLength === right.byteLength && left.digest === right.digest;
146	}
147	
148	function sameClosure(left: readonly GenerationRef[], right: readonly GenerationRef[]): boolean {
149		return left.length === right.length && left.every((ref, index) => sameRef(ref, right[index] as GenerationRef));
150	}
151	
152	function sameHead(left: PresentHead, right: PresentHead): boolean {
153		return (
154			left.closureDigest === right.closureDigest &&
155			left.generationId === right.generationId &&
156			left.objectId === right.objectId &&
157			left.revision === right.revision
158		);
159	}
160	
161	function canonicalRecord(bytes: Uint8Array): Readonly<Record<string, unknown>> | undefined {
162		try {
163			const decoded = decodeCanonical(bytes);
164			return record(decoded) && sameBytes(encodeCanonical(decoded), bytes) ? decoded : undefined;
165		} catch {
166			return undefined;
167		}
168	}
169	
170	function exactClosureDigest(references: readonly GenerationRef[], expected: string): boolean {
171		const digested = digestClosure(references);
172		return digested.ok && digested.value === expected;
173	}
174	
175	async function readLineage(
176		store: AheDurableStore,
177		objectId: SealedAdoptionFacts["objectId"]
178	): Promise<readonly GenerationRecord[] | undefined> {
179		const output: GenerationRecord[] = [];
180		const cursors = new Set<GenerationPageCursor>();
181		let cursor: GenerationPageCursor | undefined;
182		for (;;) {
183			const result = await store.readGenerationPage({
184				...(cursor === undefined ? {} : { cursor }),
185				limit: 128,
186				objectId,
187			});
188			if (!result.ok || (result.value.generations.length === 0 && result.value.nextCursor !== null)) return undefined;
189			output.push(...result.value.generations);
190			if (result.value.nextCursor === null) return Object.freeze(output);
191			if (cursors.has(result.value.nextCursor)) return undefined;
192			cursors.add(result.value.nextCursor);
193			cursor = result.value.nextCursor;
194		}
