197	async function loadClosure(
198		store: AheDurableStore,
199		references: readonly GenerationRef[]
200	): Promise<readonly Candidate[] | undefined> {
201		const candidates: Candidate[] = [];
202		for (const ref of references) {
203			const loaded = await store.getBlob(ref.digest);
204			if (!loaded.ok || loaded.value === null || loaded.value.byteLength !== ref.byteLength) return undefined;
205			const digest = digestBlob(loaded.value);
206			if (!digest.ok || digest.value !== ref.digest) return undefined;
207			candidates.push(Object.freeze({ bytes: Uint8Array.from(loaded.value), ref: Object.freeze({ ...ref }) }));
208		}
209		return Object.freeze(candidates);
210	}
