375	async function authenticatedTerminal(
376		facts: SealedAdoptionFacts,
377		material: CreatorAdoptionIntentMaterial
378	): Promise<Terminal> {
379		try {
380			if (
381				!sameHead(material.pendingHead, facts.proposedHead) ||
382				!sameClosure(material.pendingReferences, facts.proposedReferences) ||
383				material.pendingHead.objectId !== facts.objectId
384			) {
385				return Object.freeze({ kind: "chain-invalid" });
386			}
387			const recovered = await facts.store.recoverActiveGeneration(facts.objectId);
388			if (!recovered.ok || recovered.value.kind !== "active") {
389				return Object.freeze({ kind: "recovery-failed" });
390			}
391			const active = recovered.value;
392			const pending = sameHead(active.head, material.pendingHead);
393			const candidateDigest = digestClosure(material.candidateReferences);
394			const candidate =
395				candidateDigest.ok &&
396				active.head.objectId === material.pendingHead.objectId &&
397				active.head.revision === material.pendingHead.revision + 1 &&
398				active.head.closureDigest === candidateDigest.value &&
399				active.adoptedGeneration.state === "Adopted" &&
400				sameClosure(active.references, material.candidateReferences) &&
401				sameClosure(active.adoptedGeneration.closure, material.candidateReferences);
402			if (!pending && !candidate) return Object.freeze({ kind: "stale-head" });
403			if (
404				active.adoptedGeneration.state !== "Adopted" ||
405				!sameClosure(active.references, pending ? material.pendingReferences : material.candidateReferences) ||
406				!sameClosure(
407					active.adoptedGeneration.closure,
408					pending ? material.pendingReferences : material.candidateReferences
409				) ||
410				!exactClosureDigest(active.references, active.head.closureDigest)
411			) {
412				return Object.freeze({ kind: "chain-invalid" });
413			}
414			const [generations, currentCandidates, pendingCandidates, activeCandidates] = await Promise.all([
415				readLineage(facts.store, facts.objectId),
416				loadClosure(facts.store, facts.currentReferences),
417				loadClosure(facts.store, facts.proposedReferences),
418				loadClosure(facts.store, pending ? material.pendingReferences : material.candidateReferences),
419			]);
420			const descriptor = validProjection(material);
421			if (
422				generations === undefined ||
423				currentCandidates === undefined ||
424				pendingCandidates === undefined ||
425				activeCandidates === undefined ||
426				descriptor === undefined ||
427				!validLineage(generations, facts, material, active.head, candidate) ||
428				!validTrustChain(facts, currentCandidates, pendingCandidates)
429			) {
430				return Object.freeze({ kind: "chain-invalid" });
431			}
432			const predecessor = currentCandidates.filter(
433				({ bytes, ref }) =>
434					sameRef(ref, material.predecessorLiveRef) && canonicalRecord(bytes)?.kind === "v3-live-generation-1"
435			);
436			return predecessor.length === 1
437				? Object.freeze({ head: Object.freeze({ ...active.head }), kind: candidate ? "active-new" : "pending-old" })
438				: Object.freeze({ kind: "chain-invalid" });
439		} catch {
440			return Object.freeze({ kind: "recovery-failed" });
441		}
442	}
