505	async function stageCandidate(facts: SealedAdoptionFacts, material: CreatorAdoptionIntentMaterial): Promise<void> {
506		const scope = Object.freeze({ generationId: material.generationId, objectId: facts.objectId });
507		if (
508			!successfulMutation(
509				await facts.store.beginGeneration({
510					...scope,
511					baseExpectedHead: material.pendingHead,
512					closure: material.candidateReferences,
513				})
514			)
515		) {
516			throw new TypeError("creator successor begin failed");
517		}
518		const projectionDigest = digestBlob(material.exactCanonicalProjectionBytes);
519		if (
520			!projectionDigest.ok ||
521			!successfulMutation(
522				await facts.store.putCachedBlob({
523					...scope,
524					bytes: material.exactCanonicalProjectionBytes,
525					digest: projectionDigest.value,
526				})
527			)
528		) {
529			throw new TypeError("creator successor projection cache failed");
530		}
531		const predecessorAclBytes = material.activation.predecessorExactCanonicalLatchedAclBytes;
532		const predecessorAclDigest = digestBlob(predecessorAclBytes);
533		if (
534			!predecessorAclDigest.ok ||
535			!successfulMutation(
536				await facts.store.putCachedBlob({
537					...scope,
538					bytes: predecessorAclBytes,
539					digest: predecessorAclDigest.value,
540				})
541			)
542		) {
543			throw new TypeError("creator predecessor ACL cache failed");
544		}
545		for (const ref of material.candidateReferences) {
546			if (!successfulMutation(await facts.store.promoteReference({ ...scope, digest: ref.digest }))) {
547				throw new TypeError("creator successor promotion failed");
548			}
549		}
550		if (!successfulMutation(await facts.store.completeGeneration(scope))) {
551			throw new TypeError("creator successor completion failed");
552		}
553	}
