634		const facts = resolveCreatorAdoptionFacts<SealedAdoptionFacts>(captured.handle);
635		const staged = consumeStagedCreatorSuccessorAdoption(captured.capability, captured.handle);
636		if (facts === undefined || staged === undefined) {
